def gen(rng):
    def fmt(a):
        return f'{len(a)}\n' + ' '.join(map(str, a))
    def make(n, missing=None):
        vals = list(range(n + 1))
        if missing is None:
            missing = rng.randint(0, n)
        vals.remove(missing)
        rng.shuffle(vals)
        return vals
    tests = [fmt([0]), fmt([1]), fmt([0, 1]), fmt([1, 2]), fmt([2, 0]), fmt([3, 1, 0, 2])]
    for _ in range(6):
        tests.append(fmt(make(rng.randint(2, 20))))
    N = 100000
    tests.append(fmt(make(N, 0)))
    tests.append(fmt(make(N, N)))
    tests.append(fmt(make(N)))
    tests.append(fmt(list(range(1, N + 1))))
    return tests

